/* Christmas HQ — Cinematic Panel Theme v1
   Page-specific Christmas scenes, shared snow, bold festive headings, dark nav. */
(()=>{
'use strict';
if(window.__hqPanelThemeV1)return; window.__hqPanelThemeV1=true;
const scenes={"home":"data:image/webp;base64,","gifts":"data:image/webp;base64,","plan":"data:image/webp;base64,","kitchen":"data:image/webp;base64,","magic":"data:image/webp;base64,","games":"data:image/webp;base64,","chat":"data:image/webp;base64,","explore":"data:image/webp;base64,","settings":"data:image/webp;base64,"};
const labels={home:'CHRISTMAS HQ',gifts:'Gifts',plan:'Plan',kitchen:'Kitchen',magic:'Magic',games:'Games',chat:'Chat',explore:'Explore',settings:'Settings'};

const st=document.createElement('style');
st.id='hqPanelThemeV1Style';
st.textContent=`
.mast{
 position:relative!important;overflow:hidden!important;isolation:isolate!important;
 min-height:260px!important;background-image:
 linear-gradient(180deg,rgba(3,12,19,.16) 0%,rgba(3,17,20,.22) 42%,rgba(3,22,20,.78) 100%),
 var(--hq-panel-scene)!important;
 background-size:cover!important;background-position:center!important;background-repeat:no-repeat!important;
 border-radius:0 0 28px 28px!important;
}
.mast:before{background:linear-gradient(180deg,rgba(0,0,0,.08),transparent 45%,rgba(0,0,0,.16))!important}
.hq-home-brand,.hq-page-brand{position:relative!important;z-index:4!important;text-align:center!important;margin:0 auto!important}
.hq-home-brand .mast-name,.hq-page-title{
 color:#fff7e8!important;font-family:Georgia,'Times New Roman',serif!important;font-weight:1000!important;
 letter-spacing:-1px!important;line-height:.95!important;
 text-shadow:0 3px 0 #9d160f,0 5px 0 #67110c,0 8px 14px rgba(0,0,0,.7)!important;
 -webkit-text-stroke:1px rgba(255,255,255,.42);
}
.hq-home-brand .mast-name{
 font-size:clamp(35px,10vw,54px)!important;text-transform:uppercase!important;
 transform:perspective(420px) rotateX(-5deg) scaleX(1.04)!important;
 transform-origin:50% 100%!important;
}
.hq-page-title{font-size:clamp(39px,11vw,58px)!important}
.hq-page-subbrand,.hq-brand-flourish,.hq-catchphrase{color:#fff7df!important;text-shadow:0 2px 8px rgba(0,0,0,.8)!important}
.hq-catchphrase{font-weight:900!important}
.hq-hero-main{z-index:4!important}
.hq-bottom-row{display:flex!important;align-items:center!important;justify-content:center!important;gap:8px!important;flex-wrap:nowrap!important}
.hq-christmas-countdown{
 background:rgba(17,20,18,.78)!important;border:1px solid rgba(255,222,163,.48)!important;
 box-shadow:0 8px 24px rgba(0,0,0,.34)!important;backdrop-filter:blur(9px)!important;
}
.hq-home-buttons{display:flex!important;align-items:center!important;gap:6px!important}
.hq-settings-btn{flex:0 0 auto!important}
.hq-snow{z-index:3!important}
#nav,nav.bottom-nav,.bottom-nav{
 background:rgba(8,18,26,.97)!important;border-color:rgba(255,255,255,.10)!important;
 box-shadow:0 -5px 22px rgba(0,0,0,.24)!important;
}
#nav button,nav.bottom-nav button,.bottom-nav button{color:#f4f5f5!important}
#nav button.current,#nav button[aria-current="page"],nav.bottom-nav button.current,.bottom-nav button.current{color:#ff3038!important}
#nav button.current i,#nav button[aria-current="page"] i{filter:drop-shadow(0 0 7px rgba(255,48,56,.48))}
@media(max-width:430px){
 .mast{min-height:250px!important}
 .hq-page-title{font-size:42px!important}
 .hq-home-brand .mast-name{font-size:38px!important}
}
`;
document.head.appendChild(st);

let busy=false;
function snow(){
 if(!window.mast||mast.querySelector('.hq-snow'))return;
 const box=document.createElement('div'); box.className='hq-snow';
 for(let i=0;i<30;i++){
   const f=document.createElement('i');
   f.style.left=(Math.random()*100)+'%';
   f.style.animationDuration=(4+Math.random()*6)+'s';
   f.style.animationDelay=(-Math.random()*8)+'s';
   f.style.opacity=(.35+Math.random()*.6);
   f.style.transform='scale('+(.55+Math.random()*1.1)+')';
   box.appendChild(f);
 }
 mast.appendChild(box);
}
function apply(){
 if(busy||!window.mast||!window.ui)return; busy=true;
 try{
   const page=(mast.dataset.hqPage||ui.tab||'home').toLowerCase();
   const key=scenes[page]?page:'home';
   mast.dataset.hqPage=key;
   mast.style.setProperty('--hq-panel-scene',`url("${scenes[key]}")`);
   const title=mast.querySelector('.hq-page-title');
   if(title&&labels[key]) title.textContent=labels[key];
   const home=mast.querySelector('.hq-home-brand .mast-name');
   if(home) home.textContent='CHRISTMAS HQ';
   snow();
 }finally{busy=false}
}
const mo=new MutationObserver(()=>requestAnimationFrame(apply));
mo.observe(document.documentElement,{subtree:true,childList:true,attributes:true,attributeFilter:['data-hq-page']});
document.addEventListener('click',()=>setTimeout(apply,0),true);
apply();
})();
